/** Значение одного параметра ТТХ системы. */
export interface SpecValue {
  /** Ключ параметра из SPEC_PARAMETER_DEFS. */
  readonly parameterKey: string;
  /** Русское название параметра. */
  readonly labelRu: string;
  /** Числовое значение (все ТТХ базы — числовые). */
  readonly value: number;
  /** Единица измерения. */
  readonly unit: string;
  /** Методический комментарий к параметру. */
  readonly noteRu: string;
}

/** Страна-оператор системы. */
export interface OperatorEntry {
  /** ISO-код страны (alpha-3). */
  readonly countryIso: string;
  /** Русское название страны. */
  readonly countryRu: string;
  /** Комментарий о статусе эксплуатации. */
  readonly noteRu: string;
}

/** Эпизод боевого применения системы. */
export interface CombatUseEntry {
  /** Конфликт или операция. */
  readonly conflictRu: string;
  /** Период применения. */
  readonly periodRu: string;
  /** Что известно о применении и результатах. */
  readonly noteRu: string;
}

/** Экспертная оценка системы по шести осям (0–10). */
export interface SystemAssessment {
  /** Огневая мощь. */
  readonly firepower: number;
  /** Защищённость/живучесть. */
  readonly protection: number;
  /** Подвижность/манёвр. */
  readonly mobility: number;
  /** Осведомлённость: сенсоры, СУО, связь. */
  readonly awareness: number;
  /** Надёжность и зрелость конструкции. */
  readonly reliability: number;
  /** Экспортный потенциал. */
  readonly exportPotential: number;
}

/** Происхождение записи: источник, винтаж данных, честность оценки. */
export interface SystemProvenance {
  /** Источник данных. */
  readonly sourceRu: string;
  /** Год винтажа данных. */
  readonly dataYear: number;
  /** true, если часть ТТХ — оценки, а не опубликованные значения. */
  readonly estimated: boolean;
}

/** Полный профиль системы вооружений. */
export interface WeaponSystemProfile {
  /** Уникальный идентификатор (slug). */
  readonly id: string;
  /** Международное название. */
  readonly nameEn: string;
  /** Русское название/обозначение. */
  readonly nameRu: string;
  /** Класс вооружения. */
  readonly classId: WeaponClassId;
  /** Русское название класса. */
  readonly classRu: string;
  /** ISO-код страны-разработчика. */
  readonly developerIso: string;
  /** Страна-разработчик по-русски. */
  readonly developerRu: string;
  /** Головной производитель/разработчик. */
  readonly manufacturerRu: string;
  /** Подкласс/тип системы. */
  readonly subtypeRu: string;
  /** Статус программы. */
  readonly statusRu: string;
  /**
   * Дата, на которую актуален статус программы (ISO «ГГГГ-ММ»), —
   * отдельно от винтажа ТТХ (provenance.dataYear): статусы меняются
   * быстрее характеристик. Поле введено аудитом 2026-11-07 и заполнено
   * у систем, чей статус перепроверен по источникам 2026 года.
   */
  readonly statusAsOf?: string;
  /** Год принятия на вооружение или первого полёта/спуска. */
  readonly yearEntered: number;
  /** Поколение/технологический уровень. */
  readonly generationRu: string;
  /** Краткая сводка (2–3 предложения). */
  readonly summaryRu: string;
  /** Таблица ТТХ: одно поле — одна запись. */
  readonly specs: readonly SpecValue[];
  /** Страны-операторы. */
  readonly operators: readonly OperatorEntry[];
  /** Боевой опыт (может быть пустым у новых систем). */
  readonly combatUse: readonly CombatUseEntry[];
  /** Известные варианты и модификации. */
  readonly variantsRu: readonly string[];
  /** Экспертная оценка по шести осям. */
  readonly assessment: SystemAssessment;
  /** Источник и винтаж данных. */
  readonly provenance: SystemProvenance;
}

